 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page(viewport={'width':390,'height':844},has_touch=True);page.goto(os.environ.get('UNITY_URL','http://127.0.0.1:3483')+'/baccarat/index.html');page.locator('#settings-link').click();page.locator('[data-setting=betOrder]').select_option('area-first');page.locator('[data-action=back]').click();page.locator('[data-action=tables]').click();page.locator('[data-action="start:lounge"]').click();before=page.evaluate('()=>BACCARAT.session.state.balance');page.locator('[data-action="bet:banker"]').tap();assert page.evaluate('()=>Object.keys(BACCARAT.session.state.bets).length')==0;assert page.locator('[data-action="bet:banker"]').get_attribute('aria-pressed')=='true';page.locator('[data-action="chip:1000"]').tap();assert page.evaluate('()=>BACCARAT.session.state.bets.banker')==1000;assert page.evaluate('()=>BACCARAT.session.state.balance')==before;page.locator('[data-action="bet:player"]').tap();page.locator('[data-action="chip:5000"]').tap();assert page.evaluate('()=>BACCARAT.session.state.bets.player')==5000;page.locator('[data-action=undo]').click();assert page.evaluate('()=>!BACCARAT.session.state.bets.player');page.locator('[data-action=confirm]').click();page.locator('[data-action=skip]').click();assert page.evaluate('()=>BACCARAT.session.state.stats.rounds')==1;page.reload();page.locator('[data-action=continue]').click();page.locator('[data-action=next]').click();assert page.locator('.chip').first.is_disabled();page.locator('[data-action="bet:player"]').tap();page.locator('[data-action="chip:1000"]').tap();assert page.evaluate('()=>BACCARAT.session.state.bets.player')==1000;b.close()
